    quad.unk80 = 0xFF9000000260L;
    quad.unk70 = 0;
    FastVecSub(&mat[3], g_debug_camera, pos);
    vec_scale_to_length(&mat[3], &mat[3], 0.3f);
    FastVecAdd(&mat[3], &mat[3], pos);
    mat[3].f[3] = 1.0f;
