// Draws a ribbon of quads along a polyline, in two passes with edge colouring.
void draw_walloper_arc_two_pass_quads(char *m, int a, int b, int n, float sx, float sy, float sz) {
    RW q[4];
    RT t;
    RW q2[4];
    RT u;
    RW w120, w130, w140, w150, r160, r170, a180, b190, s1A0, s1B0;
    int i, col0, col1;
    float len, len0, l0, l1;
    t.q0 = GetEffectTex(*(int *)&walloper_arc_inner_tex);
    col0 = *(int *)&walloper_arc_inner_color | (a << 24);
    t.q2 = 0x8000000048L;
    t.q1 = 0xFF9000000260L;
    t.z4 = 0;
    t.c[3] = col0;
    t.c[2] = col0;
    t.c[1] = col0;
    t.c[0] = col0;
    u.q0 = GetEffectTex(*(int *)&walloper_arc_outer_tex);
    col1 = *(int *)&walloper_arc_outer_color | (b << 24);
    u.q2 = t.q2;
    u.q1 = t.q1;
    u.z4 = t.z4;
    u.c[3] = col1;
    u.c[2] = col1;
    u.c[1] = col1;
    u.c[0] = col1;
    u.f[0] = 0; u.f[1] = 0; u.f[2] = 0; u.f[3] = 1.0f; u.f[4] = 1.0f; u.f[5] = 0; u.f[6] = 1.0f; u.f[7] = 1.0f;
    t.f[0] = 0; t.f[1] = 0; t.f[2] = 0; t.f[3] = 1.0f; t.f[4] = 1.0f; t.f[5] = 0; t.f[6] = 1.0f; t.f[7] = 1.0f;
    FastVecSub(w140, m, g_debug_camera);
    FastVecSub(w150, m + 0x10, m);
    FastVecCross(w120, w150, w140);
    len0 = FastVecLength(w120);
    if (len0 != 0) len0 = 1.0f / len0;
    FastVecScale(w120, w120, sx * len0);
    FastVecAdd(q[0], m, w120);
    FastVecSub(q[1], m, w120);
    for (i = 1; i < n - 1; i++) {
        FastVecSub(w140, m + i * 16, g_debug_camera);
        FastVecSub(w150, m + i * 16 + 16, m + i * 16);
        FastVecCross(w120, w150, w140);
        len = FastVecLength(w120);
        if (len != 0) len = 1.0f / len;
        FastVecScale(w120, w120, sx * len);
        FastVecAdd(q[2], m + i * 16, w120);
        FastVecSub(q[3], m + i * 16, w120);
        if (i == 1) {
            t.c[1] = *(int *)&walloper_arc_inner_color;
            t.c[0] = *(int *)&walloper_arc_inner_color;
        } else if (i == n - 2) {
            t.c[3] = *(int *)&walloper_arc_inner_color;
            t.c[2] = *(int *)&walloper_arc_inner_color;
        } else if (i == 2) {
            t.c[1] = col0;
            t.c[0] = col0;
        }
        draw_world_quad(q, 0, 0);
        qcopy(q[0], q[2]);
        qcopy(q[1], q[3]);
    }
    for (i = 0; i < n - 1; i++) {
        FastVecSub(a180, m + i * 16, g_debug_camera);
        FastVecSub(b190, m + i * 16 + 16, g_debug_camera);
        l0 = FastVecLength(a180);
        l1 = FastVecLength(b190);
        if (l1 < l0) {
            if (l1 == 0) qcopy(b190, a180);
            else FastVecScale(b190, b190, l0 / l1);
        } else {
            if (l0 == 0) qcopy(a180, b190);
            else FastVecScale(a180, a180, l1 / l0);
        }
        FastVecAdd(r160, g_debug_camera, a180);
        FastVecAdd(r170, g_debug_camera, b190);
        FastVecSub(w150, r170, r160);
        FastVecScale(s1B0, w150, sz);
        FastVecSub(r160, r160, s1B0);
        FastVecAdd(r170, r170, s1B0);
        FastVecSub(s1A0, g_debug_camera, r160);
        FastVecCross(w120, s1A0, w150);
        len = FastVecLength(w120);
        if (len != 0) len = 1.0f / len;
        FastVecScale(w130, w120, sy * len);
        FastVecAdd(q2[0], r160, w130);
        FastVecSub(q2[1], r160, w130);
        FastVecAdd(q2[2], r170, w130);
        FastVecSub(q2[3], r170, w130);
        if (i == 0) {
            u.c[1] = *(int *)&walloper_arc_outer_color;
            u.c[0] = *(int *)&walloper_arc_outer_color;
        } else if (i == n - 2) {
            u.c[3] = *(int *)&walloper_arc_outer_color;
            u.c[2] = *(int *)&walloper_arc_outer_color;
        } else if (i == 1) {
            u.c[1] = col1;
            u.c[0] = col1;
        }
        draw_world_quad(q2, 0, 0);
    }
    VU1_addGSregister(0x47, 0x5360B);
}
