/* builds a four-vector billboard quad around a point and runs the draw packet */
void draw_walloper_camera_facing_quad(int arg) {
    char *m = (char *)arg;
    W q[4];
    T t;
    W c, d, e, bb, tmp, a, f;
    float (*p)[4];
    int i, col, r;
    float *qq;
    float *cc;
    FastVecScale(a, m + 0xD0, *(float *)&walloper_glow_forward_offset);
    FastVecAdd(bb, a, m + 0x10);
    t.q0 = GetEffectTex(*(int *)&walloper_glow_tex);
    t.q2 = 0x8000000048L;
    t.q1 = 0xFF9000000260L;
    t.z4 = 0;
    t.z0 = 0;
    t.z1 = 0;
    t.z2 = 0;
    t.f0 = 1.0f;
    t.f1 = 1.0f;
    t.z3 = 0;
    t.f2 = 1.0f;
    t.f3 = 1.0f;
    if (random_integer_below(4) == 0) {
        col = *(int *)&walloper_glow_flicker_color;
    } else {
        col = *(int *)&walloper_glow_color;
    }
    r = truncate_float_to_s32_r(IntToFloat(col >> 24) * walloper_effect_fade_m);
    col = (col & 0xFFFFFF) | (r << 24);
    cc = c;
    t.c[3] = col;
    t.c[2] = col;
    t.c[1] = col;
    t.c[0] = col;
    FastVecSub(f, g_debug_camera, bb);
    vec_scale_to_length(cc, f, 1.0f);
    FastVecCross(d, cc, hero_globals_base + 0x10AD);
    vec_scale_to_length(d, d, -1.0f);
    FastVecCross(e, d, cc);
    FastVecScale(f, cc, 0.2f);
    FastVecAdd(bb, bb, f);
    p = walloper_glow_quad_corners;
    qq = q[0];
    for (i = 3; i >= 0; i--) {
        FastVecScale(tmp, p, *(float *)&walloper_glow_quad_size);
        p++;
        transform_vector(qq, tmp, c);
        qq += 4;
    }
    draw_world_quad(q, 0, 0);
}
