/* Steps a vector by n repeated additions of the normalised difference. */
void accumulate_local_vector_steps(char *a, char *b, int n) {
    float d[4];
    float t[4];
    int i;
    FastVecSub(d, b, a);
    FastVecScale(d, d, 1.0f / IntToFloat(n));
    qcopy(t, a);
    for (i = 0; i < n; i++) {
        FastVecAdd(t, t, d);
    }
}
