/*
 * Nudges a copy of a0's vector by -0.3/+1.0 on Z, hands both to the
 * particle spawner (func_L00_001EFFF0), and lets an active state check
 * or a small dispatch table (keyed by func_L00_001F3958's result)
 * override the default return value (a0's byte at +0x20) with 11.
 */
int compute_moby_state_from_vertical_probe(EffectSrc *a0) {
    Vec4f v1, v2;
    int result;

    result = a0->field20;
    qcopy(&v1, &a0->vec);
    qcopy(&v2, &a0->vec);
    v1.z -= 0.3f;
    v2.z += 1.0f;
    if (coll_line(&v2, &v1, 6, a0, 0) != 0) {
        TopStruct *p = g_coll_hit_moby;
        if (p != 0) {
            SubStruct *sub = p->sub;
            if (sub != 0) {
                if (sub->field46 == 5) {
                    result = 11;
                    goto end;
                }
            }
        }
        switch (CollType()) {
        case 0:
        case 1:
        case 3:
        case 8:
        case 11:
        case 12:
        case 13:
            result = 11;
            break;
        }
    }
end:
    return result;
}
